param(
    [string]$ProjectRoot = "",
    [switch]$SkipInitialBuild,
    [switch]$SkipFinalBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

try {
    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
    $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
} catch {}

$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$ExpectedSha = "E4C9D5DAB8B2933C7BBD2216E1CAD110D2A291F55400D57FB7B86A9D66D3BD43"
$DesiredSha = "B731FC4D066C52A02187FA485753A675F743A5A221B4923D5491F503C8A43411"
$MarkerExpected = "ORCALY_ORDER_WHATSAPP_UNICODE_V2"
$MarkerNew = "ORCALY_ORDER_WHATSAPP_PERCENT_EMOJI_V3"

if ([string]::IsNullOrWhiteSpace($ProjectRoot)) {
    $ProjectRoot = (Get-Location).Path
} else {
    $ProjectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
}

$Target = Join-Path $ProjectRoot "lib\order-whatsapp.ts"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot (".orcaly-backups\whatsapp-percent-emoji-" + $Timestamp)
$BackupFile = Join-Path $BackupRoot "lib\order-whatsapp.ts"

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function Sha([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return ""
    }

    return (
        Get-FileHash -LiteralPath $Path -Algorithm SHA256
    ).Hash.ToUpperInvariant()
}

function Restore {
    if (Test-Path -LiteralPath $BackupFile -PathType Leaf) {
        Copy-Item -LiteralPath $BackupFile -Destination $Target -Force
        Warn "Rollback concluido."
    }
}

try {
    Write-Host ""
    Write-Host "ORCALY - WHATSAPP EMOJI URL V3" -ForegroundColor Cyan
    Write-Host "Emojis inseridos como bytes UTF-8 percent-encoded na URL." -ForegroundColor DarkCyan

    if (-not (Test-Path -LiteralPath (Join-Path $ProjectRoot "package.json") -PathType Leaf)) {
        throw "Execute na raiz do projeto Orcaly."
    }

    Set-Location $ProjectRoot

    if (-not (Test-Path -LiteralPath $Target -PathType Leaf)) {
        throw "lib/order-whatsapp.ts nao encontrado."
    }

    $current = [IO.File]::ReadAllText($Target)

    if ($current.Contains($MarkerNew)) {
        Ok "A correcao V3 ja esta aplicada."
        exit 0
    }

    if (-not $current.Contains($MarkerExpected)) {
        throw "A versao Unicode anterior nao foi identificada."
    }

    if ((Sha $Target) -ne $ExpectedSha) {
        throw (
            "lib/order-whatsapp.ts mudou desde a versao auditada. " +
            "O script recusou sobrescrever. SHA atual: " +
            (Sha $Target)
        )
    }

    Ok "Gerador corresponde exatamente a versao Unicode V2 auditada."

    if (-not $SkipInitialBuild) {
        Step "Build inicial"
        & npm.cmd run build

        if ($LASTEXITCODE -ne 0) {
            throw "O projeto ja falha no build antes da correcao."
        }

        Ok "Build inicial passou."
    }

    Step "Backup"

    [IO.Directory]::CreateDirectory((Split-Path -Parent $BackupFile)) | Out-Null
    Copy-Item -LiteralPath $Target -Destination $BackupFile -Force
    Ok ("Backup: " + $BackupFile)

    Step "Aplicando emojis percent-encoded"

    $bytes = [Convert]::FromBase64String("")
    $content = [Text.Encoding]::UTF8.GetString($bytes)
    [IO.File]::WriteAllText($Target, $content, $Utf8NoBom)

    if ((Sha $Target) -ne $DesiredSha) {
        throw "Conteudo gravado diverge do conteudo validado."
    }

    $after = [IO.File]::ReadAllText($Target)

    if (-not $after.Contains($MarkerNew)) {
        throw "Marcador V3 ausente."
    }

    if (-not $after.Contains("%F0%9F%93%A6")) {
        throw "Byte sequence do emoji de pacote ausente."
    }

    if (-not $after.Contains("replaceAll")) {
        throw "Substituicao de placeholders ausente."
    }

    if ($after.Contains("\u{1F4E6}")) {
        throw "Escape Unicode antigo ainda existe."
    }

    Ok "Emojis agora sao inseridos somente depois do encodeURIComponent."

    Step "Lint"
    & npx.cmd eslint "lib/order-whatsapp.ts"

    if ($LASTEXITCODE -ne 0) {
        throw "Lint falhou."
    }

    Ok "Lint passou."

    if (-not $SkipFinalBuild) {
        Step "Build final"
        & npm.cmd run build

        if ($LASTEXITCODE -ne 0) {
            throw "Build final falhou."
        }

        Ok "Build final passou."
    }

    Write-Host ""
    Write-Host "WHATSAPP EMOJI URL V3 APLICADO" -ForegroundColor Green
    Write-Host ""
    Write-Host "Os emojis nao passam mais pelo encoder JavaScript como caracteres."
    Write-Host "Eles entram na URL final como sequencias UTF-8 percent-encoded."
    Write-Host ""
    Write-Host "Nenhum banco, API, checkout, commit, push ou deploy foi alterado." -ForegroundColor Cyan
}
catch {
    Write-Host ""
    Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red

    if (Test-Path -LiteralPath $BackupFile -PathType Leaf) {
        Restore
    }

    Write-Host ("Backup/diagnostico: " + $BackupRoot) -ForegroundColor Yellow
    exit 1
}
